pub type User = { name: Str; age: Int; }

impl Clone for User {
  fn clone(self: &User) -> User {
    return User{ name: self.name.clone(), age: self.age };
  }
}

fn main() -> Int {
  let u = User{ name: "Alice", age: 30 };
  let mut u2 = u.clone();
  u2.age = 31;
  return u2.age;
}
